import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { Row, Table, Avatar, Alert } from 'antd'
import { connect } from 'react-redux'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import ProfileWrapperStyled from './index.style'

class ProfilePage extends PureComponent {
  state = {
    profile: {},
    errorMessage: ''
  }

  constructor (props) {
    super(props)
    this.columns = [
      {
        dataIndex: 'name',
        width: 150
      },
      {
        dataIndex: 'id'
      },
      {
        dataIndex: 'value'
      }
    ]
  }

  componentDidUpdate () {
    const { profile, profileMessage } = this.props.profileData
    if (Object.values(profile).length > 0) {
      const { user } = profile
      this.setState({ profile: user })
    }
    if (profileMessage !== undefined) {
      this.setState({ errorMessage: profileMessage })
    }
  }

  render () {
    const { profile, errorMessage } = this.state
    let data = []
    if (profile && Object.values(profile).length > 0) {
      data = [{
        key: '1',
        name: 'ID',
        value: profile.id || '-'
      }, {
        key: '2',
        name: 'Email',
        value: profile.email || '-'
      }, {
        key: '3',
        name: 'Name',
        value: profile.name || '-'
      }, {
        key: '4',
        name: 'Phone',
        value: profile.phone || '-'
      }]
    }
    return (
      <ProfileWrapperStyled>
        <LayoutContentWrapper>
          {
            (errorMessage) && (
              <Alert
                className='error-alert'
                message={<strong>{errorMessage}</strong>}
                type='error'
                closeText='Close'
              />
            )
          }
          <LayoutContent className='layout-content'>
            <div className='avatar-container'>
              <Avatar className='avatar' size='large'>
                {profile && Object.values(profile).length > 0 && profile.email[0].toUpperCase()}
              </Avatar>
            </div>
            <Row className='row-table'>
              <Table showHeader={false} columns={this.columns} dataSource={data} />
            </Row>
          </LayoutContent>
        </LayoutContentWrapper>
      </ProfileWrapperStyled>
    )
  }
}

ProfilePage.propTypes = {
  profileData: PropTypes.object.isRequired
}

ProfilePage.defaultProps = {
  profileData: {}
}

export default connect(
  state => ({
    profileData: state.Auth
  }),
  {}
)(ProfilePage)
